/// A real 2×2 PNG — garbage bytes would throw on the test event loop.
final Uint8List _tinyPng = base64Decode(
  'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAE0lEQVR4nGPQvbIfiBga'
  'e34AEQAw3weL9bEH6gAAAABJRU5ErkJggg==',
);

void main() {
  Widget wrap(Widget child) => MaterialApp(
    theme: buildFahTheme(),
    home: Scaffold(body: Center(child: child)),
  );

  group('fahMarkdownStyleSheet', () {
    test('body text is pinned to the dense chat line height', () {
      final sheet = fahMarkdownStyleSheet(buildFahTheme());
      expect(sheet.p?.height, 1.35);
      expect(sheet.listBullet?.height, 1.35);
      expect(sheet.h1?.height, 1.3);
    });

    test('sizes are explicit even when the theme text theme is null-sized', () {
      // The current Flutter ships M3 text themes with null fontSize — the
      // stylesheet must still resolve concrete sizes (fromTheme asserts).
      final sheet = fahMarkdownStyleSheet(buildFahTheme());
      expect(sheet.p?.fontSize, 14);
      expect(sheet.h1?.fontSize, 28);
      expect(sheet.h2?.fontWeight, FontWeight.w700);
    });

    test('fontSize scales the body and keeps heading proportions', () {
      final sheet = fahMarkdownStyleSheet(buildFahTheme(), fontSize: 18);
      expect(sheet.p?.fontSize, 18);
      expect(sheet.h1?.fontSize, 36);
      expect(sheet.h3?.fontSize, closeTo(24.3, 0.01));
      expect(sheet.listBullet?.fontSize, 18);
      expect(sheet.code?.fontSize, closeTo(16.56, 0.01));
    });
  });

  group('SandboxImageResolver.sizedImageBuilder', () {
    // The framed-image dimensions/constraints every successful arm shares.
    void expectFramed(WidgetTester tester) {
      final image = tester.widget<Image>(find.byType(Image));
      expect(image.fit, BoxFit.fitWidth);
      final box = tester.widget<ConstrainedBox>(
        find
            .ancestor(
              of: find.byType(Image),
              matching: find.byType(ConstrainedBox),
            )
            .first,
      );
      expect(box.constraints.maxHeight, 320);
      final clip = tester.widget<ClipRRect>(
        find.ancestor(of: find.byType(Image), matching: find.byType(ClipRRect)),
      );
      expect(clip.borderRadius, BorderRadius.circular(8));
    }

    testWidgets('data: URIs decode inline and report taps', (tester) async {
      Uint8List? tapped;
      final resolver = SandboxImageResolver(MemoryExecutionEnv());
      await tester.pumpWidget(
        wrap(
          MarkdownBody(
            data:
                '![swatch](data:image/png;base64,'
                '${base64Encode(_tinyPng)})',
            sizedImageBuilder: resolver.sizedImageBuilder(
              onImageTap: (bytes) => tapped = bytes,
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      expectFramed(tester);
      final bytes =
          (tester.widget<Image>(find.byType(Image)).image as MemoryImage).bytes;
      expect(bytes, _tinyPng);

      // Invoke the tap wiring directly: the real hit test needs the image
      // decoded (real async, unavailable under fake-async pumpAndSettle).
      tester
          .widget<GestureDetector>(find.byType(GestureDetector))
          .onTap!
          .call();
      expect(tapped, _tinyPng);
    });

    testWidgets('sandbox paths load through the env', (tester) async {
      final env = MemoryExecutionEnv();
      await env.writeBinaryFile('generated/x.png', _tinyPng);
      final resolver = SandboxImageResolver(env);
      await tester.pumpWidget(
        wrap(
          MarkdownBody(
            data: '![chart](generated/x.png)',
            sizedImageBuilder: resolver.sizedImageBuilder(),
          ),
        ),
      );
      await tester.pumpAndSettle();

      expectFramed(tester);
      expect(find.byIcon(Icons.broken_image_outlined), findsNothing);
    });

    testWidgets('a leading slash still resolves inside the sandbox', (
      tester,
    ) async {
      final env = MemoryExecutionEnv();
      await env.writeBinaryFile('generated/x.png', _tinyPng);
      final resolver = SandboxImageResolver(env);
      await tester.pumpWidget(
        wrap(
          MarkdownBody(
            data: '![chart](/generated/x.png)',
            sizedImageBuilder: resolver.sizedImageBuilder(),
          ),
        ),
      );
      await tester.pumpAndSettle();

      expectFramed(tester);
    });

    testWidgets('missing sandbox files degrade to the placeholder line', (
      tester,
    ) async {
      final resolver = SandboxImageResolver(MemoryExecutionEnv());
      await tester.pumpWidget(
        wrap(
          MarkdownBody(
            data: '![nope](generated/gone.png)',
            sizedImageBuilder: resolver.sizedImageBuilder(),
          ),
        ),
      );
      await tester.pumpAndSettle();

      expect(find.byType(Image), findsNothing);
      expect(find.byIcon(Icons.broken_image_outlined), findsOneWidget);
      expect(find.text('nope'), findsOneWidget);
    });

    testWidgets('http(s) images degrade to the placeholder on failure', (
      tester,
    ) async {
      // The test binding's mocked HTTP client answers 400 — the error
      // builder must show the placeholder, never a red box.
      final resolver = SandboxImageResolver(MemoryExecutionEnv());
      await tester.pumpWidget(
        wrap(
          MarkdownBody(
            data: '![remote](https://example.invalid/x.png)',
            sizedImageBuilder: resolver.sizedImageBuilder(),
          ),
        ),
      );
      await tester.pumpAndSettle();

      expect(find.byIcon(Icons.broken_image_outlined), findsOneWidget);
      expect(find.text('remote'), findsOneWidget);
    });
  });
}

import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart'
    show ExecutionEnv;
import 'package:flutter_markdown/flutter_markdown.dart';

import '../theme/app_theme.dart';

/// The app's shared [MarkdownStyleSheet]: theme text with the landing
/// palette's teal links, mono inline code, and bordered code blocks /
/// quotes — resolved per brightness, so the light theme gets the light
/// palette. Used by the chat transcript and the file browser's Markdown
/// preview so both render Markdown identically.
///
/// [fontSize] overrides the body size (the chat text-size setting); every
/// style scales by the same factor so headings keep their proportions.
/// Sizes are EXPLICIT, never inherited: the current Flutter ships M3 text
/// themes with null fontSize (fromTheme's assert kills debug builds, and
/// release silently collapsed headings to body size). Line height is
/// pinned at 1.35 / 1.3 for headings — the M3 defaults (1.43–1.5) read as
/// double-spaced in a dense chat transcript.
MarkdownStyleSheet fahMarkdownStyleSheet(ThemeData theme, {double? fontSize}) {
  const bodyHeight = 1.35;
  const headingHeight = 1.3;
  final body = fontSize ?? theme.textTheme.bodyMedium?.fontSize ?? 14.0;
  final bodyStyle = (theme.textTheme.bodyMedium ?? const TextStyle())
      .copyWith(fontSize: body, height: bodyHeight);
  TextStyle heading(double factor, FontWeight weight) => bodyStyle.copyWith(
    fontSize: body * factor,
    fontWeight: weight,
    height: headingHeight,
  );
  final isLight = theme.brightness == Brightness.light;
  final teal = isLight ? FahLightPalette.teal : FahPalette.teal;
  final indigo = isLight ? FahLightPalette.indigo : FahPalette.indigo;
  final panelAlt = isLight ? FahLightPalette.panelAlt : FahPalette.panelAlt;
  final border = isLight ? FahLightPalette.border : FahPalette.border;
  final codeBg = isLight ? FahLightPalette.codeBg : FahPalette.codeBg;
  final codeStyle = isLight ? FahLightPalette.mono() : FahPalette.mono();
  // fromTheme asserts a non-null bodyMedium fontSize — hand it a theme
  // whose bodyMedium is guaranteed resolved.
  final safeTheme = theme.copyWith(
    textTheme: theme.textTheme.copyWith(bodyMedium: bodyStyle),
  );
  return MarkdownStyleSheet.fromTheme(safeTheme).copyWith(
    p: bodyStyle,
    a: TextStyle(color: teal, fontSize: body, height: bodyHeight),
    h1: heading(2.0, FontWeight.w700),
    h2: heading(1.6, FontWeight.w700),
    h3: heading(1.35, FontWeight.w600),
    h4: heading(1.15, FontWeight.w600),
    h5: heading(1.0, FontWeight.w600),
    h6: heading(0.95, FontWeight.w500),
    listBullet: bodyStyle,
    code: codeStyle.copyWith(
      fontSize: body * 0.92,
      backgroundColor: codeBg,
    ),
    codeblockDecoration: BoxDecoration(
      color: panelAlt,
      borderRadius: BorderRadius.circular(8),
      border: Border.all(color: border),
    ),
    codeblockPadding: const EdgeInsets.all(10),
    blockquoteDecoration: BoxDecoration(
      border: Border(left: BorderSide(color: indigo, width: 3)),
    ),
  );
}

/// Resolves Markdown images that point into the agent's sandbox
/// (`![alt](generated/x.png)`, optionally with a leading `/`) by loading
/// the bytes through the session [ExecutionEnv].
///
/// One resolver per chat surface: loads are memoized so transcript rebuilds
/// do not re-read the sandbox on every frame. Missing, unreadable, or
/// undecodable files degrade to a small dim placeholder line — never a
/// crash or a red error box.
final class SandboxImageResolver {
  /// Creates a resolver reading through [env].
  SandboxImageResolver(this.env);

  /// The sandbox filesystem image paths resolve against.
  final ExecutionEnv env;

  final Map<String, Future<Uint8List?>> _cache = {};

  /// Bytes of the sandbox file at [path] (a leading `/` is stripped), or
  /// null when the file is missing or unreadable.
  Future<Uint8List?> load(String path) {
    final clean = path.startsWith('/') ? path.substring(1) : path;
    return _cache.putIfAbsent(clean, () async {
      final result = await env.readBinaryFile(clean);
      return result.valueOrNull;
    });
  }

  /// A [MarkdownSizedImageBuilder] for `MarkdownBody(sizedImageBuilder: …)`.
  ///
  /// `http(s)` URIs load over the network; `data:` URIs decode inline;
  /// everything else is treated as a sandbox-relative path. Taps on a
  /// successfully loaded image go to [onImageTap] (fullscreen preview).
  MarkdownSizedImageBuilder sizedImageBuilder({
    void Function(Uint8List bytes)? onImageTap,
  }) {
    return (config) {
      final uri = config.uri;
      final alt = config.alt ?? config.title;
      if (uri.scheme == 'http' || uri.scheme == 'https') {
        return _framedNetworkImage(uri, alt: alt);
      }
      if (uri.scheme == 'data') {
        return _framedImage(
          bytes: UriData.parse(uri.toString()).contentAsBytes(),
          alt: alt,
          onTap: onImageTap,
        );
      }
      return image(path: uri.path, alt: alt, onTap: onImageTap);
    };
  }

  /// The inline image for the sandbox file at [path]: a bounded,
  /// rounded-corner thumbnail while loading, the decoded image on success
  /// (tap → [onTap]), or a dim placeholder line on failure.
  Widget image({
    required String path,
    String? alt,
    void Function(Uint8List bytes)? onTap,
    double maxHeight = 320,
  }) {
    return FutureBuilder<Uint8List?>(
      future: load(path),
      builder: (context, snapshot) {
        if (snapshot.connectionState != ConnectionState.done) {
          return _loadingBox(context);
        }
        final bytes = snapshot.data;
        if (bytes == null) return _placeholder(context, alt ?? path);
        return _framedImage(
          bytes: bytes,
          alt: alt,
          onTap: onTap,
          maxHeight: maxHeight,
        );
      },
    );
  }

  Widget _framedImage({
    required Uint8List bytes,
    String? alt,
    void Function(Uint8List bytes)? onTap,
    double maxHeight = 320,
  }) {
    Widget child = Image.memory(
      bytes,
      fit: BoxFit.fitWidth,
      errorBuilder: (context, _, _) => _placeholder(context, alt ?? 'image'),
    );
    child = ClipRRect(
      borderRadius: BorderRadius.circular(8),
      child: ConstrainedBox(
        constraints: BoxConstraints(maxHeight: maxHeight),
        child: child,
      ),
    );
    if (onTap != null) {
      child = GestureDetector(onTap: () => onTap(bytes), child: child);
    }
    return Padding(padding: const EdgeInsets.only(top: 4), child: child);
  }

  Widget _framedNetworkImage(Uri uri, {String? alt}) {
    return Padding(
      padding: const EdgeInsets.only(top: 4),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(8),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxHeight: 320),
          child: Image.network(
            uri.toString(),
            fit: BoxFit.fitWidth,
            errorBuilder: (context, _, _) =>
                _placeholder(context, alt ?? uri.toString()),
          ),
        ),
      ),
    );
  }

  Widget _loadingBox(BuildContext context) {
    final palette = FahColors.of(context);
    return Padding(
      padding: const EdgeInsets.only(top: 4),
      child: Container(
        height: 48,
        decoration: BoxDecoration(
          color: palette.panelAlt,
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: palette.border),
        ),
        child: Center(
          child: SizedBox(
            width: 14,
            height: 14,
            child: CircularProgressIndicator(
              strokeWidth: 2,
              color: palette.dim,
            ),
          ),
        ),
      ),
    );
  }

  Widget _placeholder(BuildContext context, String label) {
    final palette = FahColors.of(context);
    return Padding(
      padding: const EdgeInsets.only(top: 4),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.broken_image_outlined, size: 14, color: palette.dim),
          const SizedBox(width: 6),
          Flexible(
            child: Text(
              label,
              overflow: TextOverflow.ellipsis,
              style: palette.mono(color: palette.dim, fontSize: 12),
            ),
          ),
        ],
      ),
    );
  }
}

/// A [MarkdownSizedImageBuilder] over [env] — see [SandboxImageResolver].
///
/// Each call creates a fresh resolver (and cache); surfaces that rebuild
/// often should hold one [SandboxImageResolver] instead.
MarkdownSizedImageBuilder fahSandboxImageBuilder(
  ExecutionEnv env, {
  void Function(Uint8List bytes)? onImageTap,
}) => SandboxImageResolver(env).sizedImageBuilder(onImageTap: onImageTap);

/// Fullscreen, zoomable preview gallery for [images] — shared by the chat
/// screen's Markdown images / `generate_image` tool tiles and the user
/// bubble attachments (swipe walks one message's images, issue #461).
void showFahImagePreview(
  BuildContext context,
  List<Uint8List> images, {
  int initialIndex = 0,
}) {
  showDialog<void>(
    context: context,
    builder: (context) => Dialog(
      backgroundColor: Colors.black,
      insetPadding: EdgeInsets.zero,
      child: _FahImageGallery(images: images, initialIndex: initialIndex),
    ),
  );
}

/// The gallery route body: one zoomable page per image, a close button and
/// a page counter. Pinch zooms; a horizontal fling at scale 1.0 flips the
/// page (pan is ceded to the viewer only while zoomed in).
class _FahImageGallery extends StatefulWidget {
  const _FahImageGallery({required this.images, required this.initialIndex});

  final List<Uint8List> images;
  final int initialIndex;

  @override
  State<_FahImageGallery> createState() => _FahImageGalleryState();
}

class _FahImageGalleryState extends State<_FahImageGallery> {
  late final PageController _controller = PageController(
    initialPage: widget.initialIndex.clamp(0, widget.images.length - 1),
  );
  late int _page = _controller.initialPage;
  double _scale = 1;

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Stack(
      children: [
        PageView.builder(
          controller: _controller,
          itemCount: widget.images.length,
          onPageChanged: (page) => setState(() => _page = page),
          itemBuilder: (context, index) => InteractiveViewer(
            panEnabled: _scale > 1,
            maxScale: 5,
            onInteractionUpdate: (details) =>
                _scale = details.scale,
            child: Center(child: Image.memory(widget.images[index])),
          ),
        ),
        SafeArea(
          child: Row(
            mainAxisAlignment: MainAxisAlignment.end,
            children: [
              IconButton(
                icon: const Icon(Icons.close, color: Colors.white),
                tooltip: MaterialLocalizations.of(
                  context,
                ).closeButtonTooltip,
                onPressed: Navigator.of(context).pop,
              ),
            ],
          ),
        ),
        if (widget.images.length > 1)
          Align(
            alignment: Alignment.bottomCenter,
            child: SafeArea(
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Text(
                  '${_page + 1} / ${widget.images.length}',
                  style: const TextStyle(color: Colors.white70),
                ),
              ),
            ),
          ),
      ],
    );
  }
}

import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

import 'chat_strings.dart';
import 'fa_chat_host.dart';

/// The slice of the chat backend [ApprovalModeSelector] needs: a listenable
/// holding the live [ApprovalManager] plus a mode setter. [FaChatService]
/// already carries both members, so any chat backend satisfies this.
abstract interface class FaApprovalModeController implements Listenable {
  /// The approval manager whose mode the selector reflects.
  ApprovalManager get approval;

  /// Applies a new approval mode.
  void setApprovalMode(ApprovalMode mode);
}

/// Renders an approval prompt as a Material dialog — the Flutter/web
/// [ApprovalPrompt] surface. The host chat screen installs this on
/// [FaChatService.approvalPromptHandler].
///
/// Dismissing the dialog (barrier tap, back button) maps to
/// [ApprovalDecision.deny]: an unanswered prompt must never allow a call.
///
/// When [modeController] is provided the dialog offers a "YOLO mode —
/// allow everything" checkbox: toggling it switches the SESSION approval
/// mode live (toggle off restores the mode the dialog opened with).
Future<ApprovalDecision> showApprovalPrompt(
  BuildContext context,
  ApprovalRequest request, {
  FaApprovalModeController? modeController,
}) async {
  final decision = await showDialog<ApprovalDecision>(
    context: context,
    builder: (_) =>
        ApprovalDialog(request: request, modeController: modeController),
  );
  return decision ?? ApprovalDecision.deny;
}

/// The three-button tool approval dialog: approve once, always allow the
/// tool for the session, or deny. Pops with the chosen [ApprovalDecision],
/// or `null` when dismissed. With a [modeController] it also carries the
/// session-wide yolo checkbox.
class ApprovalDialog extends StatefulWidget {
  const ApprovalDialog({super.key, required this.request, this.modeController});

  /// The approval request being decided.
  final ApprovalRequest request;

  /// Session approval-mode controller behind the yolo checkbox; null
  /// hides the checkbox (the classic three-button dialog).
  final FaApprovalModeController? modeController;

  @override
  State<ApprovalDialog> createState() => _ApprovalDialogState();
}

class _ApprovalDialogState extends State<ApprovalDialog> {
  static const _maxArgumentChars = 800;

  /// The mode the dialog opened with — unchecking yolo restores it.
  ApprovalMode? _previousMode;
  bool _yolo = false;

  @override
  void initState() {
    super.initState();
    final controller = widget.modeController;
    if (controller != null) {
      _previousMode = controller.approval.mode;
      _yolo = _previousMode == ApprovalMode.yolo;
    }
  }

  void _onYoloChanged(bool? checked) {
    final controller = widget.modeController;
    if (controller == null || checked == null) return;
    setState(() => _yolo = checked);
    controller.setApprovalMode(
      checked ? ApprovalMode.yolo : (_previousMode ?? ApprovalMode.alwaysAsk),
    );
  }

  String _formattedArguments() {
    var encoded = '';
    try {
      encoded = const JsonEncoder.withIndent(
        '  ',
      ).convert(widget.request.arguments);
    } on Object {
      encoded = widget.request.arguments.toString();
    }
    if (encoded.length > _maxArgumentChars) {
      encoded = '${encoded.substring(0, _maxArgumentChars)}…';
    }
    return encoded;
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final request = widget.request;
    return AlertDialog(
      title: Text(
        FaChatStrings.of(context).approvalAllowToolTitle(request.toolName),
      ),
      content: SizedBox(
        width: 420,
        child: SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(request.reason),
              const SizedBox(height: 8),
              Text(
                FaChatStrings.of(context).approvalTierLabel(request.tier.name),
                style: theme.textTheme.bodySmall,
              ),
              const SizedBox(height: 12),
              Container(
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: theme.colorScheme.surfaceContainerHighest,
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  _formattedArguments(),
                  style: theme.textTheme.bodySmall?.copyWith(
                    fontFamily: 'JetBrainsMono',
                  ),
                ),
              ),
              if (widget.modeController != null) ...[
                const SizedBox(height: 4),
                CheckboxListTile(
                  value: _yolo,
                  onChanged: _onYoloChanged,
                  controlAffinity: ListTileControlAffinity.leading,
                  contentPadding: EdgeInsets.zero,
                  title: Text(
                    FaChatStrings.of(context).approvalYoloAllowEverything,
                    style: theme.textTheme.bodyMedium,
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(ApprovalDecision.deny),
          style: TextButton.styleFrom(foregroundColor: theme.colorScheme.error),
          child: Text(FaChatStrings.of(context).approvalDeny),
        ),
        TextButton(
          onPressed: () =>
              Navigator.of(context).pop(ApprovalDecision.approveOnce),
          child: Text(FaChatStrings.of(context).approvalAllowOnce),
        ),
        FilledButton(
          onPressed: () =>
              Navigator.of(context).pop(ApprovalDecision.approveAlways),
          child: Text(FaChatStrings.of(context).approvalAlwaysAllow),
        ),
      ],
    );
  }
}

/// The three-segment approval mode selector shown in the settings dialog:
/// `always-ask` prompts for every tool call, `write` prompts for mutating
/// and shell tools, `yolo` allows everything (critical bash patterns still
/// prompt). Bound live to [FaApprovalModeController.approval].
class ApprovalModeSelector extends StatelessWidget {
  const ApprovalModeSelector({super.key, required this.service});

  /// The service whose approval mode the segments switch.
  final FaApprovalModeController service;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return AnimatedBuilder(
      animation: service,
      builder: (context, _) {
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              FaChatStrings.of(context).approvalModeTitle,
              style: theme.textTheme.titleSmall,
            ),
            const SizedBox(height: 8),
            SegmentedButton<ApprovalMode>(
              segments: [
                ButtonSegment(
                  value: ApprovalMode.alwaysAsk,
                  label: Text(FaChatStrings.of(context).approvalModeAlwaysAsk),
                ),
                ButtonSegment(
                  value: ApprovalMode.write,
                  label: Text(FaChatStrings.of(context).approvalModeWrite),
                ),
                ButtonSegment(
                  value: ApprovalMode.yolo,
                  label: Text(FaChatStrings.of(context).approvalModeYolo),
                ),
              ],
              selected: {service.approval.mode},
              onSelectionChanged: (modes) {
                FaChatHost.track('approval_mode_changed', {
                  'mode': modes.first.name,
                });
                service.setApprovalMode(modes.first);
              },
            ),
            const SizedBox(height: 8),
            Text(switch (service.approval.mode) {
              ApprovalMode.alwaysAsk => FaChatStrings.of(
                context,
              ).approvalModeAlwaysAskHint,
              ApprovalMode.write => FaChatStrings.of(
                context,
              ).approvalModeWriteHint,
              ApprovalMode.yolo => FaChatStrings.of(
                context,
              ).approvalModeYoloHint,
              ApprovalMode.unattended => FaChatStrings.of(
                context,
              ).approvalModeYoloHint,
            }, style: theme.textTheme.bodySmall),
          ],
        );
      },
    );
  }
}

